					// dist-info directory (https://py-pkgs.org/04-package-structure.html#building-sdists-and-wheels)
					regexp.MustCompile(`(?i)(?:^|/)[a-z0-9_.]+-[0-9.]+\.dist-info(?:/.+)?$`),

